// Payload de Alertmanager. Las resoluciones (status=resolved) no se analizan ni se notifican por email:
// van a 'Resolve Incident'. A las alertas activas se les aplica el umbral: si no se supera, devuelve [] y corta.
const body = ($input.first().json.body) || $input.first().json || {};
const alerts = Array.isArray(body.alerts) ? body.alerts : [];
const status = body.status || 'firing';
const first = alerts[0] || {};
const ann = body.commonAnnotations || first.annotations || {};
const labels = body.commonLabels || first.labels || {};
const alertname = labels.alertname || (first.labels && first.labels.alertname) || 'unknown';
const severity = labels.severity || (first.labels && first.labels.severity) || 'warning';
if (status !== 'resolved') {
  const threshold = parseInt($env.ALERT_THRESHOLD || '3', 10);
  const hasCritical = alerts.some(a => a.labels && a.labels.severity === 'critical');
  if (!(alerts.length >= threshold || hasCritical)) return [];
}
const summary = ann.summary || alertname || 'Alerta sin resumen';
const description = ann.description || '';
// Mismo texto para buscar en el RAG y para guardar el incidente: así la próxima ocurrencia lo reconoce.
const query_text = description ? `${summary}. ${description}` : summary;
// Alertmanager manda endsAt=0001-01-01 mientras la alerta sigue activa.
const validDate = (d) => (d && !String(d).startsWith('0001-')) ? d : null;
return [{ json: {
  summary, description, alertname, severity, query_text,
  alertsCount: alerts.length,
  status,
  starts_at: validDate(first.startsAt) || new Date().toISOString(),
  ends_at: validDate(first.endsAt)
} }];

// Combina la alerta (nodo Prepare) con el contexto RAG para armar el prompt del modelo LLM.
const prep = $('Prepare').item.json;
const rag = $json || {};
const results = Array.isArray(rag.results) ? rag.results.slice(0, 3) : [];
// Solución de cada match: los runbooks traen 'pasos'; los auto-documentados, solo 'documento' (se usa su sección
// de pasos, o el inicio del documento): así el análisis aprovecha lo que la plataforma aprendió.
const solutionOf = (r) => {
  const pasos = (r.pasos || []).filter(Boolean);
  if (pasos.length) return `Pasos: ${pasos.join(' | ')}`;
  const doc = String(r.documento || '').trim();
  if (!doc) return 'Sin solución registrada.';
  const m = doc.match(/##\s*Pasos de resoluci[oó]n[^\n]*\n([\s\S]*?)(?=\n##\s|$)/i);
  const text = (m ? m[1] : doc).trim().replace(/\n{2,}/g, '\n');
  return `Solución documentada:\n${text.length > 900 ? text.slice(0, 900) + '…' : text}`;
};
const contextLines = results.map((r, i) =>
  `${i + 1}. [score ${Number(r.score).toFixed(3)} · ${r.clasificacion}] ${r.tipo_alerta}: ${r.resumen}\n   ${solutionOf(r).replace(/\n/g, '\n   ')}`
).join('\n');
const system = 'Sos un analista de AIOps. Dado el contexto de una alerta y datos históricos de incidentes, sintetizá el problema en términos técnicos claros y proponé pasos de resolución accionables y numerados. Sé conciso. Respondé en español. Si el contexto histórico aplica, referencialo. Entorno de Argos: un único host con Docker Compose (proyecto argos-platform), sin Kubernetes ni systemd. Contenedores: nginx-proxy (reverse proxy, puerto 80), membresia-api (API .NET, upstream de Nginx; en el host :5000), membresia-sqlserver (SQL Server de la API), nginx-prometheus-exporter (:9113), node-exporter (:9100), cadvisor (:8080), alloy (envía los logs de Nginx a Loki), argos-platform-prometheus-1, argos-platform-loki-1, argos-platform-alertmanager-1, argos-platform-grafana-1. En los comandos usá esos nombres reales (docker ps -a, docker logs, docker start/restart).';
const user = `Alerta: ${prep.alertname} (severidad: ${prep.severity})\nResumen: ${prep.summary}\nDescripción: ${prep.description}\nAlertas activas en el grupo: ${prep.alertsCount}\n\nContexto histórico (RAG, documentado=${rag.is_documented}):\n${contextLines || 'Sin coincidencias relevantes.'}\n\nSintetizá el problema y proponé pasos de resolución.`;
return [{ json: { system, user, prep, is_documented: !!rag.is_documented } }];

// Respuesta de rag-api /internal/llm/generate (cadena de fallback entre proveedores). Si fallaron todos
// (onError=continue), la alerta sigue igual: email con aviso y el incidente queda 'nuevo' para documentar a mano.
const resp = $json || {};
const llmOk = typeof resp.text === 'string' && resp.text.trim().length > 0;
const errorMsg = (resp.error && (resp.error.message || resp.error.description)) || 'sin detalle';
const text = llmOk
  ? resp.text.trim()
  : `⚠️ Análisis IA no disponible: ningún proveedor LLM respondió (${errorMsg}). El incidente quedó registrado en Argos para documentarlo desde el dashboard.`;
const bp = $('Build Prompt').item.json;
const prep = bp.prep;
const isNew = bp.is_documented === false;
const autoDoc = ($('Get Config').item.json || {}).auto_doc_enabled !== false;
const badgeText = autoDoc && llmOk
  ? '🆕 Incidente nuevo — auto-documentado por Argos'
  : '🆕 Incidente nuevo — pendiente de documentar';
const badge = isNew ? `<p style="color:#b45309"><strong>${badgeText}</strong></p>` : '';
const via = llmOk ? `<small>IA: ${resp.provider}/${resp.model}${resp.fallback_used ? ' (proveedor de respaldo)' : ''}</small><br>` : '';
const html = `<h2>[ALERTA] ${prep.alertname} — ${prep.severity}</h2>` + badge +
  `<p><strong>Resumen:</strong> ${prep.summary}</p>` +
  `<pre style="white-space:pre-wrap;font-family:inherit">${text}</pre>` +
  `<hr>${via}<small>Generado por Argos (n8n + IA).</small>`;
return [{ json: {
  analysis: text, html, alertname: prep.alertname, severity: prep.severity, summary: prep.summary,
  is_documented: bp.is_documented, llm_ok: llmOk, llm_provider: resp.provider || null,
  llm_model: resp.model || null, fallback_used: !!resp.fallback_used
} }];

// Sin documentación automática (auto-doc desactivada en el dashboard o IA caída en el análisis):
// se registra el incidente NUEVO sin documento (estado 'nuevo') para documentarlo a mano ('Generar documentación').
const prep = $('Build Prompt').item.json.prep;
const incident = {
  tipo_alerta: prep.alertname,
  resumen: prep.query_text,
  pasos: [],
  severity: prep.severity,
  fuente: 'alertmanager',
  estado: 'nuevo',
  detected_at: prep.starts_at
};
return [{ json: { incident } }];

// Incidente NUEVO (sin match en la KB): arma el prompt para generar documentación técnica.
const prep = $('Build Prompt').item.json.prep;
const system = 'Sos un ingeniero SRE documentando un incidente NUEVO para la base de conocimiento de Argos. Generá documentación técnica concisa en Markdown con estas secciones exactas: "# Título", "## Descripción", "## Causa raíz probable", "## Pasos de resolución" (lista numerada), "## Prevención". Respondé en español y devolvé SOLO el Markdown, sin texto adicional. Entorno de Argos: un único host con Docker Compose (proyecto argos-platform), sin Kubernetes ni systemd. Contenedores: nginx-proxy (reverse proxy, puerto 80), membresia-api (API .NET, upstream de Nginx; en el host :5000), membresia-sqlserver (SQL Server de la API), nginx-prometheus-exporter (:9113), node-exporter (:9100), cadvisor (:8080), alloy (envía los logs de Nginx a Loki), argos-platform-prometheus-1, argos-platform-loki-1, argos-platform-alertmanager-1, argos-platform-grafana-1. En los comandos usá esos nombres reales (docker ps -a, docker logs, docker start/restart).';
const user = `Alerta: ${prep.alertname} (severidad: ${prep.severity})
Resumen: ${prep.summary}
Descripción: ${prep.description}
Alertas activas en el grupo: ${prep.alertsCount}

Este incidente NO existe en la base de conocimiento de Argos. Generá su documentación técnica completa.`;
return [{ json: { system, user } }];

// Markdown generado por rag-api (cadena de fallback). Si falló toda la cadena, el incidente se registra igual
// como 'nuevo' sin documento, para documentarlo después desde el dashboard.
const resp = $json || {};
const text = typeof resp.text === 'string' ? resp.text.trim() : '';
const documented = text.length > 0;
const prep = $('Build Prompt').item.json.prep;
const incident = {
  tipo_alerta: prep.alertname,
  resumen: prep.query_text,
  pasos: [],
  severity: prep.severity,
  fuente: documented ? 'auto-generado' : 'alertmanager',
  estado: documented ? 'auto_documentado' : 'nuevo',
  detected_at: prep.starts_at
};
if (documented) incident.documento = text;
return [{ json: { incident } }];

// Pool configurado en el dashboard (rag-api /notifications/recipients). Si viene vacío o la
// llamada falló (onError=continue), fallback a ALERT_RECIPIENT_EMAIL para no perder la alerta.
const list = Array.isArray($json.recipients) ? $json.recipients.filter(Boolean) : [];
const to = list.length ? list.join(', ') : ($env.ALERT_RECIPIENT_EMAIL || '');
if (!to) {
  throw new Error('Sin destinatarios configurados (pool vacío y ALERT_RECIPIENT_EMAIL sin definir)');
}
return [{ json: { to, recipients_source: list.length ? 'pool' : 'env', recipients_count: list.length || 1 } }];
